const rl = readline.createInterface({ input: process.stdin, terminal: false });
let lines = [];

rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    let arr = lines[0].split(' ');
    let first = arr[0];
    let sec = arr[1];
    let n = parseInt(lines[1]);

    for (let i = n; i > 1; i--) {
        if (n - 4 >= 1) {
            n = n - 4;
        } else {
            break;
        }
    }

    let all = "<^>v";
    let start = 0;
    let end = 0;

    for (let i = 0; i < all.length; i++) {
        if (first[0] === all[i]) {
            start = i;
        }
        if (sec[0] === all[i]) {
            end = i;
        }
    }

    if (start === end || start === end - 2 || start === end + 2) {
        console.log("undefined");
    } else {
        if ((start === end - 1 && n === 1) || (start === end + 3 && n === 1) || (start === end - 3 && n !== 1) || (start === end + 1 && n !== 1)) {
            console.log("cw");
        } else if ((start === end - 3 && n === 1) || (start === end + 1 && n === 1) || (start === end - 1 && n !== 1) || (start === end + 3 && n !== 1)) {
            console.log("ccw");
        }
    }
});
